56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    /**
59	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
60	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
61	     */
62	    private static final Pattern EMAIL_PATTERN =
63	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        String telephone = normalizeTelephone(owner.getTelephone());
114	        if (telephone.length() != 10) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        owner.setTelephone(telephone);
118	        if (owner.getEmail() != null) {
119	            String email = normalizeEmail(owner.getEmail());
120	            if (!EMAIL_PATTERN.matcher(email).matches()) {
121	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
122	            }
123	            owner.setEmail(email);
124	        }
125	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
126	            .anyMatch(existing -> telephone.equals(normalizeTelephone(existing.getTelephone())));
127	        if (telephoneInUse) {
128	            return new ResponseEntity<>(HttpStatus.CONFLICT);
129	        }
130	        this.clinicService.saveOwner(owner);
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
136	
137	    /**
138	     * Normalizes a telephone number for creation by stripping every non-digit character,
139	     * leaving only the digits. Callers require the result to be exactly 10 digits.
140	     *
141	     * @param telephone the raw telephone value (may be {@code null})
142	     * @return the digits-only telephone (never {@code null})
143	     */
144	    private String normalizeTelephone(String telephone) {
145	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
146	    }
147	
148	    /**
149	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
150	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
151	     *
152	     * @param email the raw email value (must not be {@code null})
153	     * @return the trimmed, lower-cased email
